import { useCallback, useMemo, useState } from "react";
import {
	AlertTriangle,
	Check,
	Globe,
	Loader2,
	Plus,
	RotateCcw,
	Save,
	Wifi,
	WifiOff,
	X,
	ChevronDown,
	ChevronUp,
} from "lucide-react";
import { useRulesConfig } from "@/context/useRulesConfig";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";
import type { RuleMetadata } from "@$REPO_SLOPGATE";
import { getPendingChangesList } from "./model";

interface RuleCommandBandProps {
	allRules: RuleMetadata[];
}

export function RuleCommandBand({ allRules }: RuleCommandBandProps) {
	const {
		config,
		savedConfig,
		pendingCount,
		setSkipPaths,
		saveConfig,
		discardChanges,
		saveStatus,
		saveError,
		apiAvailable,
		loading,
	} = useRulesConfig();

	const [draftPath, setDraftPath] = useState("");
	const [showPendingPanel, setShowPendingPanel] = useState(false);

	const paths = useMemo(() => config.skip_paths ?? [], [config.skip_paths]);

	const addPath = useCallback(() => {
		const p = draftPath.trim();
		if (!p || paths.includes(p)) return;
		setSkipPaths([...paths, p]);
		setDraftPath("");
	}, [draftPath, paths, setSkipPaths]);

	const removePath = useCallback(
		(p: string) => {
			setSkipPaths(paths.filter((x) => x !== p));
		},
		[paths, setSkipPaths],
	);

	// Category and totals computation
	const totals = useMemo(() => {
		const total = allRules.length;
		const hookEnabled = allRules.filter(
			(r) => r.hookSupported && r.hookEnabled,
		).length;
		const hookDisabled = allRules.filter(
			(r) => r.hookSupported && !r.hookEnabled,
		).length;
		const cliEnabled = allRules.filter(
			(r) => r.cliSupported && r.cliEnabled,
		).length;
		const cliDisabled = allRules.filter(
			(r) => r.cliSupported && !r.cliEnabled,
		).length;
		const activeFired = allRules.filter(
			(r) => r.enabled && r.fireCount > 0,
		).length;

		// Group counts by category
		const categoryCounts: Record<string, { total: number; enabled: number; fired: number }> = {};
		for (const r of allRules) {
			if (!categoryCounts[r.category]) {
				categoryCounts[r.category] = { total: 0, enabled: 0, fired: 0 };
			}
			categoryCounts[r.category].total++;
			if (r.enabled) {
				categoryCounts[r.category].enabled++;
			}
			if (r.fireCount > 0) {
				categoryCounts[r.category].fired++;
			}
		}

		return {
			total,
			hookEnabled,
			hookDisabled,
			cliEnabled,
			cliDisabled,
			activeFired,
			categoryCounts,
		};
	}, [allRules]);

	// Pending changes list
	const pendingList = useMemo(() => {
		return getPendingChangesList(savedConfig, config, allRules);
	}, [savedConfig, config, allRules]);

	const skipPathsChanged = useMemo(() => {
		const savedPaths = savedConfig.skip_paths ?? [];
		return (
			JSON.stringify([...savedPaths].sort()) !==
			JSON.stringify([...paths].sort())
		);
	}, [savedConfig.skip_paths, paths]);

	if (loading) return null;

	return (
		<div className="space-y-4 font-sans text-[1rem]">
			{/* Top Bar: Title, Connection Status, Actions */}
			<div className="flex flex-col md:flex-row md:items-center justify-between gap-4 py-2 border-b border-border">
				<div className="flex items-center gap-3">
					<div className="flex items-center gap-2">
						<span
							className={cn(
								"flex items-center gap-1.5 px-2.5 py-1 rounded text-[0.875rem] font-medium border",
								apiAvailable
									? "bg-signal-allow/10 text-signal-allow border-signal-allow/25"
									: "bg-muted text-muted-foreground border-border"
							)}
						>
							{apiAvailable ? (
								<>
									<Wifi className="w-4 h-4 text-signal-allow animate-pulse" />
									API Connected
								</>
							) : (
								<>
									<WifiOff className="w-4 h-4" />
									Read-Only (No API)
								</>
							)}
						</span>
					</div>

					{pendingCount > 0 && (
						<button
							type="button"
							onClick={() => setShowPendingPanel((p) => !p)}
							className="flex items-center gap-1.5 px-2.5 py-1 rounded bg-signal-ask/10 text-signal-ask border border-signal-ask/25 hover:bg-signal-ask/20 transition-colors text-[0.875rem] font-medium"
						>
							<span>{pendingCount} Pending Change{pendingCount !== 1 ? "s" : ""}</span>
							{showPendingPanel ? (
								<ChevronUp className="w-3.5 h-3.5" />
							) : (
								<ChevronDown className="w-3.5 h-3.5" />
							)}
						</button>
					)}
				</div>

				{/* Save / Discard Actions */}
				<div className="flex items-center gap-3">
					{pendingCount > 0 && (
						<>
							<button
								type="button"
								onClick={() => saveConfig()}
								disabled={saveStatus === "saving" || !apiAvailable}
								className="flex items-center gap-2 px-3 py-1.5 rounded bg-signal-allow text-white font-medium hover:bg-signal-allow/90 disabled:opacity-50 transition-colors text-[0.875rem]"
							>
								{saveStatus === "saving" ? (
									<Loader2 className="w-4 h-4 animate-spin" />
								) : (
									<Save className="w-4 h-4" />
								)}
								Save to Littlebox
							</button>
							<button
								type="button"
								onClick={discardChanges}
								className="flex items-center gap-2 px-3 py-1.5 rounded bg-muted/50 text-muted-foreground hover:bg-muted transition-colors text-[0.875rem] font-medium border border-border"
							>
								<RotateCcw className="w-4 h-4" />
								Discard
							</button>
						</>
					)}

					{pendingCount === 0 && saveStatus === "saved" && (
						<span className="text-signal-allow flex items-center gap-1.5 text-[0.875rem]">
							<Check className="w-4 h-4" /> Config Saved
						</span>
					)}

					{saveStatus === "error" && saveError && (
						<span className="text-signal-block text-[0.875rem] flex items-center gap-1.5">
							<AlertTriangle className="w-4 h-4" /> {saveError}
						</span>
					)}
				</div>
			</div>

			{/* Pending Changes Review Panel */}
			{pendingCount > 0 && showPendingPanel && (
				<div className="p-3 border border-signal-ask/30 bg-signal-ask/5 rounded-md space-y-2">
					<div className="text-[0.875rem] font-semibold text-signal-ask">
						Review Pending Modifications
					</div>
					<div className="max-h-48 overflow-y-auto space-y-1 divide-y divide-border">
						{skipPathsChanged && (
							<div className="py-1 flex items-center justify-between text-[0.875rem]">
								<span className="font-mono text-foreground font-medium">Global skip_paths</span>
								<span className="text-muted-foreground text-[0.75rem]">Modified exclusions</span>
							</div>
						)}
						{pendingList.map((item) => (
							<div key={item.rule_id} className="py-1 flex flex-col sm:flex-row sm:items-center justify-between text-[0.875rem]">
								<span className="font-mono text-foreground font-medium">{item.rule_id}</span>
								<span className="text-muted-foreground text-[0.75rem]">
									{item.fields.join(", ")}
								</span>
							</div>
						))}
					</div>
				</div>
			)}

			{/* Global skip_paths Section */}
			<div className="p-4 border border-border rounded-md bg-card/10 space-y-3">
				<div className="flex items-center gap-2">
					<Globe className="w-4 h-4 text-muted-foreground" />
					<span className="font-medium text-[0.875rem]">Global Path Exclusions</span>
					<span className="text-[0.75rem] text-muted-foreground">
						(suppresses repo-strict/project rules; always-on safety rules still run)
					</span>
				</div>

				<div className="flex flex-wrap gap-2 min-h-[28px]">
					{paths.length === 0 && (
						<span className="text-[0.875rem] text-muted-foreground italic">
							No global exclusions configured.
						</span>
					)}
					{paths.map((p) => (
						<span
							key={p}
							className="flex items-center gap-1.5 px-2 py-1 bg-muted rounded text-[0.875rem] font-mono border border-border"
						>
							{p}
							<button
								type="button"
								onClick={() => removePath(p)}
								className="hover:text-signal-block text-muted-foreground/60 hover:text-foreground transition-colors"
								aria-label={`Remove path ${p}`}
							>
								<X className="w-3.5 h-3.5" />
							</button>
						</span>
					))}
				</div>

				<div className="flex gap-2 max-w-md">
					<Input
						value={draftPath}
						onChange={(e) => setDraftPath(e.target.value)}
						onKeyDown={(e) => e.key === "Enter" && addPath()}
						placeholder="e.g., src/legacy/** or **/generated/**"
						className="h-8 text-[0.875rem] font-mono bg-background"
					/>
					<button
						type="button"
						onClick={addPath}
						disabled={!draftPath.trim()}
						className="flex items-center gap-1.5 px-3 py-1 text-[0.875rem] font-medium rounded bg-primary/10 text-primary border border-primary/20 hover:bg-primary/20 disabled:opacity-40 transition-colors whitespace-nowrap"
					>
						<Plus className="w-3.5 h-3.5" /> Add Exclusion
					</button>
				</div>
			</div>

			{/* Operational Status (Category summaries + Totals) */}
			<div className="py-2.5 border-y border-border">
				{/* Compact global numbers */}
				<div className="flex flex-wrap items-center gap-x-4 gap-y-2 text-[0.875rem] text-muted-foreground mb-2">
					<span className="font-semibold text-foreground">
						Console Status:
					</span>
					<span>Total Rules: <strong className="text-foreground">{totals.total}</strong></span>
					<span>•</span>
					<span>Hook: <strong className="text-signal-allow">{totals.hookEnabled} on</strong> / <strong className="text-muted-foreground/80">{totals.hookDisabled} off</strong></span>
					<span>•</span>
					<span>CLI: <strong className="text-primary">{totals.cliEnabled} on</strong> / <strong className="text-muted-foreground/80">{totals.cliDisabled} off</strong></span>
					<span>•</span>
					<span>Active (recently firing): <strong className="text-signal-ask">{totals.activeFired}</strong></span>
				</div>

				{/* Category operational summaries */}
				<div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-x-4 gap-y-2 text-[0.75rem] text-muted-foreground/80">
					{Object.entries(totals.categoryCounts).map(([catName, counts]) => (
						<div key={catName} className="flex items-center justify-between py-0.5 border-b border-border/20">
							<span className="truncate pr-1">{catName}</span>
							<span className="font-mono text-foreground font-medium shrink-0">
								{counts.enabled}/{counts.total} ({counts.fired} fired)
							</span>
						</div>
					))}
				</div>
			</div>
		</div>
	);
}
